using System.ComponentModel.DataAnnotations;
namespace GEnergy.Api.DTOs;

public sealed record AdminStationRequest([Required, StringLength(120, MinimumLength = 2)] string Name, [Required, StringLength(250, MinimumLength = 3)] string Address, [Range(typeof(decimal), "-90", "90")] decimal Latitude, [Range(typeof(decimal), "-180", "180")] decimal Longitude, bool IsActive = true, bool IsDemo = true);
public sealed record AdminChargerRequest([Required, StringLength(30, MinimumLength = 2)] string ChargerCode, [Required, RegularExpression("^(CCS2|Type2|CHAdeMO)$")] string ConnectorType, [Range(typeof(decimal), "0.01", "999999.99")] decimal PowerKW, [Range(typeof(decimal), "0.01", "99999999.99")] decimal PricePerKWh, bool IsActive = true);
public sealed record AdminStationResponse(long Id, string Name, string Address, decimal Latitude, decimal Longitude, bool IsActive, bool IsDemo, int ChargerCount, string Version);
public sealed record AdminChargerResponse(long Id, long StationId, string StationName, string ChargerCode, string ConnectorType, decimal PowerKW, decimal PricePerKWh, bool IsActive, string ConfiguredStatus, string EffectiveStatus, string RowVersion);
public sealed record AdminDashboardResponse(DateTime ServerTimeUtc, int TotalUsers, int ActiveStations, int TotalChargers, int AvailableChargers, int ActiveBookings, int ActiveSessions, int CompletedSessions, int CompletedChargingPayments, int SuccessfulTopUps, int FailedTopUps, int RefundCount, decimal GrossChargingPayments, decimal Refunds, decimal NetChargingPayments, decimal TotalWalletBalance, string Currency, bool IsSimulated);
public sealed record AdminUserResponse(long Id, string UserCode, string Role, bool IsActive, DateTime CreatedAtUtc);
public sealed record AdminBookingResponse(long Id, string BookingCode, long StationId, string StationName, string ChargerCode, string VehicleRegistration, string BookedByUserCode, string Status, string PersistedStatus, DateTime CreatedAtUtc, DateTime ExpiresAtUtc, long? SessionId);
public sealed record AdminSessionResponse(long Id, long BookingId, string BookingCode, long StationId, string StationName, string ChargerCode, string VehicleRegistration, string StartedByUserCode, string PayerUserCode, string Status, DateTime StartedAtUtc, DateTime? EndedAtUtc, decimal InitialBatteryPercent, decimal BatteryPercent, decimal EnergyKWh, decimal Cost, string PaymentStatus, string? PaymentReference, string SettlementNote);
public sealed record AdminTransactionResponse(long Id, string Reference, string OwnerUserCode, string Type, string Status, decimal Amount, string Description, DateTime CreatedAtUtc, long? ChargingSessionId, string? OriginalReference, string? RefundReference, bool OwnerCanRefund);
public sealed record AdminWalletResponse(long Id, string OwnerUserCode, decimal Balance, DateTime UpdatedAtUtc);
